/* ---------- films: vineyard management, pests & diseases, harvest ---------- */
FILMS.push(
{id:"vmgmt",sec:"v",ch:"vgm",ic:"order",t:I3("Gestione del vigneto: impianto, potatura e spalliere","Conduite du vignoble : plantation, taille et palissage","Vineyard management: planting, pruning and trellising"),s:[
 {h:I3("Scegliere il sito","Choisir le site","Site selection"),
  c:I3("Prima di impiantare un vigneto si valuta se il luogo è adatto. Condizioni ambientali: temperatura media, pioggia, ore di sole, fertilità e drenaggio del suolo, che guidano la scelta della varietà, della densità e della forma di allevamento. Aspetti economici: vicinanza a corrente e acqua, manodopera, accesso per trattori e vendemmiatrici, costo del terreno. La varietà deve adattarsi al clima, avere un mercato e, nell'UE, essere permessa dalla legge.",
   "Avant de planter une vigne, on évalue si le lieu convient. Conditions naturelles : température moyenne, pluie, heures de soleil, fertilité et drainage du sol, qui orientent le choix du cépage, de la densité et du mode de conduite. Aspects économiques : proximité de l'électricité et de l'eau, main-d'œuvre, accès pour tracteurs et machines à vendanger, prix du terrain. Le cépage doit convenir au climat, avoir un marché et, dans l'UE, être autorisé par la loi.",
   "Before planting a vineyard the site is assessed. Environmental conditions: average temperature, rainfall, sunshine hours, soil fertility and drainage, which guide the choice of variety, planting density and training. Business considerations: access to power and water, workforce, access for tractors and harvesters, and land cost. The variety must suit the climate, have a market and, in the EU, be legally permitted."),
  v:()=>fSvg(fGround()+fRows(30,176,290,176,0)+[[60,40,w3("clima","climat","climate")],[160,40,w3("suolo","sol","soil")],[260,40,w3("varietà e leggi","cépage et lois","variety and law")],[90,100,w3("manodopera","main-d'œuvre","workforce")],[230,100,w3("costo, accessi","coût, accès","cost, access")]].map(([x,y,l],i)=>fD(i*.4,fBox(x-50,y-14,100,28,l))).join("")+fTractor(170,172),"spring")},
 {h:I3("L'impianto","La plantation","Planting"),
  c:I3("Il terreno viene ripulito, analizzato e, se serve, concimato. Le giovani viti, quasi sempre già innestate in vivaio, si piantano a mano o a macchina e spesso si proteggono dagli animali con manicotti di plastica. Per aiutarle ad attecchire a volte si permette l'irrigazione anche dove di solito è vietata. Il primo raccolto arriva di solito al terzo anno.",
   "Le terrain est défriché, analysé et, si besoin, fertilisé. Les jeunes plants, presque toujours greffés en pépinière, sont plantés à la main ou à la machine et souvent protégés des animaux par des manchons en plastique. Pour les aider à s'installer, l'irrigation est parfois permise même là où elle est normalement interdite. La première récolte arrive en général la troisième année.",
   "The site is cleared, tested and, if needed, fertilised. Young vines, usually bought pre-grafted from a nursery, are planted by hand or machine and often protected from animals by plastic sleeves. Irrigation is sometimes allowed to help them establish, even where it is otherwise prohibited. The first crop usually comes in the third year."),
  v:()=>fSvg(fGround()+`<path d="M20 120H300M20 96H300" stroke="#9aa3ab"/>`+[50,110,170,230,290].map((x,i)=>fD(i*.25,`<rect x="${x-5}" y="140" width="10" height="34" fill="rgba(220,240,220,.8)" stroke="#9aa3ab"/>${fLeaf(x,140,.6,0)}`)).join("")+`<path d="M20 172H300" stroke="#2b2b2b" stroke-width="2"/>`+fD(1.5,fChip(160,40,w3("1° raccolto: 3° anno","1re récolte : 3e année","first crop: year 3"),"#d4a23a","#2a1b20")),"spring")},
 {h:I3("Vecchie vigne e reimpianto","Vieilles vignes et replantation","Old vines and replanting"),
  c:I3("Le viti possono vivere a lungo, ma di solito si sostituiscono tra i 30 e i 50 anni. Le «vecchie vigne» danno spesso uva di grande concentrazione, ma producono meno e si ammalano di più: si cerca un equilibrio tra qualità e redditività. Dopo l'estirpo il terreno resta a riposo almeno tre anni, e il viticoltore programma i reimpianti per tenere sempre in produzione la maggior parte del vigneto.",
   "Les vignes peuvent vivre longtemps, mais on les remplace en général entre 30 et 50 ans. Les « vieilles vignes » donnent souvent un raisin très concentré, mais produisent moins et sont plus sensibles aux maladies : on cherche un équilibre entre qualité et rentabilité. Après l'arrachage, le terrain reste en jachère au moins trois ans, et le vigneron programme les replantations pour garder en production l'essentiel du vignoble.",
   "Vines can live a long time, but most are replaced at 30 to 50 years old. 'Old vines' often give fruit of great concentration, but their yields fall and they become more prone to disease: a balance is struck between quality and profitability. After grubbing up, land is left fallow for three years or more, and the grower plans a replanting cycle to keep most of the vineyard in production."),
  v:()=>fSvg(fGround()+`<g transform="translate(-60 0)">${vForm("bush","canopy",120,172)}</g>`+`<path d="M58 172C54 150 62 136 58 124" stroke="#4e321c" stroke-width="10" fill="none"/>`+fChip(60,30,w3("30–50 anni","30–50 ans","30–50 years"))+fD(1.4,`<rect x="160" y="160" width="140" height="14" fill="#7a5a3c"/>`+fChip(230,130,w3("riposo ≥ 3 anni","jachère ≥ 3 ans","fallow ≥ 3 years"))),"autumn")},
 {h:I3("Forme di allevamento: ad alberello o a cordone","Modes de conduite : en tête ou en cordon","Training: head or cordon"),
  c:I3("L'allevamento riguarda la forma del legno permanente. Le viti allevate a testa hanno poco legno permanente: solo il tronco, a volte con brevi bracci in cima; si potano a speroni o a capo a frutto. Le viti a cordone hanno uno o più bracci orizzontali permanenti e si potano a speroni: richiedono più tempo per formarsi, ma il cordone regolare facilita la meccanizzazione, come la vendemmia a macchina. Entrambe possono essere basse, per sfruttare il calore del suolo, o alte, per sfuggire al gelo.",
   "La conduite concerne la forme du bois permanent. Les vignes conduites en tête ont peu de bois permanent : seulement le tronc, parfois avec de courts bras au sommet ; on les taille en coursons ou en baguettes. Les vignes en cordon ont un ou plusieurs bras horizontaux permanents et se taillent en coursons : plus longues à former, elles facilitent la mécanisation, comme la vendange à la machine. Les deux peuvent être basses, pour profiter de la chaleur du sol, ou hautes, pour échapper au gel.",
   "Training refers to the shape of the permanent wood. Head-trained vines have little permanent wood: just a trunk, sometimes with short arms at the top; they are spur-pruned or replacement cane-pruned. Cordon-trained vines have one or more permanent horizontal arms and are usually spur-pruned: they take longer to establish, but the sturdy cordon makes mechanisation, such as machine harvesting, easier. Either can be low-trained, to use heat from the soil, or high-trained, to avoid frost."),
  v:()=>fSvg(fGround()+`<g transform="translate(-80 0) scale(1)">${vForm("headspur","bare",160,172)}</g><g transform="translate(70 0)">${vForm("cordon","bare",160,172)}</g>`+fChip(80,26,w3("a testa","en tête","head-trained"))+fChip(230,26,w3("a cordone","en cordon","cordon-trained")),"winter")},
 {h:I3("Potatura invernale a speroni","Taille d'hiver en coursons","Winter pruning: spurs"),
  c:I3("La potatura toglie legno, tralci e foglie indesiderati, dà forma alla vite e ne limita le dimensioni. Quella invernale decide quante gemme resteranno e dove, cioè quanti germogli nasceranno: le gemme devono essere ben distanziate, per una chioma ordinata. Nella potatura a speroni il legno di un anno viene accorciato a due o tre gemme; gli speroni sono distribuiti lungo il cordone o attorno alla testa.",
   "La taille retire bois, sarments et feuilles indésirables, donne forme à la vigne et limite sa taille. Celle d'hiver décide combien de bourgeons resteront et où, donc combien de rameaux pousseront : les bourgeons doivent être bien espacés pour un feuillage ordonné. En taille courte, le bois d'un an est raccourci à deux ou trois bourgeons ; les coursons sont répartis le long du cordon ou autour de la tête.",
   "Pruning removes unwanted leaves, canes and wood, shapes the vine and limits its size. Winter pruning decides how many buds remain and where, so how many shoots will grow: buds should be well spaced for a tidy canopy. In spur pruning one-year-old wood is cut back to just two or three buds; the spurs are spread along a cordon or around the head of the trunk."),
  v:()=>fSvg(fGround()+fVine("pruned")+fCall(124,104,80,60,w3("sperone: 2–3 gemme","courson : 2–3 bourgeons","spur: 2–3 buds"),1.8),"winter")},
 {h:I3("Potatura a capo a frutto (Guyot)","Taille en baguette (Guyot)","Replacement cane pruning (Guyot)"),
  c:I3("Il capo a frutto è un tratto più lungo di legno di un anno, con 8–20 gemme. Di solito se ne lasciano uno o due, legati orizzontalmente al filo; è tipico delle viti allevate a testa. È più complessa della potatura a speroni e richiede molta manodopera esperta per scegliere e legare i capi. Si chiama anche Guyot: semplice con un capo, doppio con due.",
   "La baguette est un morceau plus long de bois d'un an, avec 8 à 20 bourgeons. On en garde en général une ou deux, attachées horizontalement au fil ; c'est typique des vignes conduites en tête. Plus complexe que la taille en coursons, elle demande beaucoup de main-d'œuvre qualifiée pour choisir et attacher les baguettes. On l'appelle aussi Guyot : simple avec une baguette, double avec deux.",
   "Canes are longer sections of one-year-old wood with 8 to 20 buds. Usually only one or two are kept, tied horizontally to the trellis wire; this is typical of head-trained vines. It is more complex than spur pruning and needs a large skilled workforce to choose and tie down the canes. It is also called Guyot training: Single Guyot with one cane, Double Guyot with two."),
  v:()=>fSvg(fGround()+`<g transform="translate(-75 0)">${vForm("guyot","bare",160,172)}</g><g transform="translate(75 0)">${vForm("guyot2","bare",160,172)}</g>`+fChip(85,26,w3("Guyot semplice","Guyot simple","Single Guyot"))+fChip(235,26,w3("Guyot doppio","Guyot double","Double Guyot"))+fD(1.5,fChip(160,190,w3("capo: 8–20 gemme","baguette : 8–20 bourgeons","cane: 8–20 buds"),"#d4a23a","#2a1b20")),"winter")},
 {h:I3("Potatura verde","Taille en vert","Summer pruning"),
  c:I3("D'estate si cimano i germogli per limitare la crescita vegetativa e indirizzare lo zucchero prodotto verso l'uva invece che verso nuove foglie. Si possono anche togliere alcune foglie attorno ai grappoli, la sfogliatura, per esporli meglio al sole.",
   "En été on rogne les rameaux pour limiter la croissance végétative et diriger le sucre produit vers le raisin plutôt que vers de nouvelles feuilles. On peut aussi retirer des feuilles autour des grappes, l'effeuillage, pour mieux les exposer au soleil.",
   "In summer the canopy is trimmed to restrict vegetative growth and direct the sugar produced to the grapes rather than to new shoots and leaves. Leaves around the bunches may also be stripped so the grapes get optimum sun exposure."),
  v:()=>fSvg(fSun(280,34,14)+fGround()+vForm("cordon","canopy",160,172)+`<g><animateTransform attributeName="transform" type="translate" values="-90 0;90 0;-90 0" dur="5s" repeatCount="indefinite"/><path d="M150 50H170" stroke="#c9ced3" stroke-width="4"/><path d="M160 50V40" stroke="#c9ced3" stroke-width="2"/></g>`+[90,140,200].map((x,i)=>`<g>${fLeaf(x,110,.7,0)}<animateTransform attributeName="transform" type="translate" from="0 0" to="${i%2?10:-10} 60" dur="2s" begin="${1+i*.5}s" fill="freeze"/><animate attributeName="opacity" from="1" to="0" dur="2s" begin="${1+i*.5}s" fill="freeze"/></g>`).join(""),"summer")},
 {h:I3("Viti ad alberello, senza spalliera","Vignes en gobelet, sans palissage","Bush vines, untrellised"),
  c:I3("In alcune regioni le viti non hanno spalliera e i germogli ricadono fino a terra: sono gli alberelli, allevati a testa e potati a speroni. Sono ideali nelle zone calde, secche e soleggiate, come il Rodano meridionale o la Barossa Valley, dove l'ombra protegge l'uva. Nelle zone fresche o umide l'ombra frena la maturazione e l'aria ferma favorisce le malattie; nel Beaujolais si legano insieme le punte dei germogli per esporre i grappoli. Gli alberelli non si vendemmiano a macchina.",
   "Dans certaines régions les vignes n'ont pas de palissage et les rameaux retombent jusqu'au sol : ce sont les gobelets, conduits en tête et taillés en coursons. Ils sont idéaux dans les zones chaudes, sèches et ensoleillées, comme le Rhône méridional ou la Barossa Valley, où l'ombre protège le raisin. En zone fraîche ou humide l'ombre freine la maturation et l'air stagnant favorise les maladies ; dans le Beaujolais on attache ensemble l'extrémité des rameaux pour exposer les grappes. Les gobelets ne se vendangent pas à la machine.",
   "In some regions vines have no trellis and the shoots hang down, often to the ground: these are bush vines, head-trained and spur-pruned. They suit warm or hot, dry, sunny regions such as the Southern Rhône or the Barossa Valley, where the shade protects the grapes. In cool or wet regions the shade can hold back ripening and still air promotes disease; in Beaujolais the shoot tips are tied together to expose the bunches. Bush vines cannot be machine-harvested."),
  v:()=>fSvg(fSun(270,36,16)+fGround("#b08a5a")+[70,160,250].map(x=>vForm("bush","canopy",x,172)).join("")+fChip(160,24,w3("Rodano meridionale · Barossa","Rhône méridional · Barossa","Southern Rhône · Barossa")),"summer")},
 {h:I3("Perché la spalliera","Pourquoi le palissage","Why trellis"),
  c:I3("La spalliera è una fila di pali uniti da fili a cui si legano tralci e germogli: è la gestione della chioma. Ha tre scopi. Primo, controllare la luce: nelle zone poco soleggiate una chioma aperta espone l'uva al sole, in quelle molto soleggiate un po' d'ombra evita le scottature. Secondo, far circolare l'aria tra foglie e grappoli, fondamentale nei climi umidi contro le malattie. Terzo, facilitare la meccanizzazione: grappoli in una zona e foglie in un'altra rendono più semplici vendemmia e trattamenti.",
   "Le palissage est une rangée de piquets reliés par des fils auxquels on attache sarments et rameaux : c'est la gestion du feuillage. Il a trois buts. D'abord contrôler la lumière : dans les zones peu ensoleillées un feuillage ouvert expose le raisin, dans les zones très ensoleillées un peu d'ombre évite l'échaudage. Ensuite faire circuler l'air entre feuilles et grappes, essentiel en climat humide contre les maladies. Enfin faciliter la mécanisation : grappes d'un côté et feuilles de l'autre simplifient vendange et traitements.",
   "A trellis is a row of posts joined by wires to which canes and shoots are tied: this is canopy management. It has three purposes. First, controlling light: in less sunny regions an open canopy exposes the grapes, while in very sunny regions some shade prevents sunburn. Second, letting air circulate through leaves and grapes, vital in wet climates to fight disease. Third, aiding mechanisation: grapes in one zone and leaves in another make harvesting and spraying simpler."),
  v:()=>fSvg(fSun(280,32,13)+fGround()+vForm("cordon","canopy",160,172)+[0,1,2].map(i=>`<path d="M10 ${80+i*14}h40" stroke="#fff" stroke-width="2" stroke-linecap="round" opacity=".8"><animateTransform attributeName="transform" type="translate" from="0 0" to="260 0" dur="2.4s" begin="${i*.4}s" repeatCount="indefinite"/></path>`).join("")+fChip(70,24,w3("1 luce","1 lumière","1 light"))+fChip(160,24,w3("2 aria","2 air","2 air"))+fChip(250,24,w3("3 macchine","3 machines","3 machinery")),"summer")},
 {h:I3("La spalliera verticale (VSP)","Le palissage vertical (VSP)","Vertical Shoot Positioning (VSP)"),
  c:I3("Il sistema più diffuso è la spalliera verticale, VSP: i germogli vengono guidati verso l'alto e legati, formando una chioma stretta, aperta, ben aerata e poco ombreggiata. Si usa con potatura a speroni o a capo a frutto. Nelle zone calde e molto soleggiate le cime dei germogli non si legano e ricadono, creando ombra sull'uva; si preferisce all'alberello perché permette la vendemmia a macchina.",
   "Le système le plus répandu est le palissage vertical, VSP : les rameaux sont dirigés vers le haut et attachés, formant un feuillage étroit, ouvert, bien aéré et peu ombragé. On l'utilise avec la taille en coursons ou en baguettes. Dans les zones chaudes et très ensoleillées, l'extrémité des rameaux n'est pas attachée et retombe, ombrageant le raisin ; on le préfère au gobelet car il permet la vendange mécanique.",
   "The most widely used system is Vertical Shoot Positioning, VSP: shoots are trained upwards and tied in place, forming a single narrow canopy that is open, well aerated and largely shade-free. It works with spur or cane pruning. In hot, sunny regions the shoot tips are left untied so they flop over and shade the fruit; growers choose this over bush vines because it allows machine harvesting."),
  v:()=>fSvg(fGround()+`<g transform="translate(-80 0) scale(1)">${vForm("cordon","canopy",160,172)}</g>`+`<g transform="translate(80 0)">${vForm("vspflop","canopy",160,172)}</g>`+fChip(80,24,"VSP")+fChip(240,24,w3("VSP con cime ricadenti","VSP à rameaux retombants","VSP, tips flopping over")),"summer")},
 {h:I3("Densità d'impianto","Densité de plantation","Planting density"),
  c:I3("La densità è il numero di viti per ettaro, cioè per un quadrato di 100 metri di lato; un acro è circa 0,4 ettari. Va da 1000 a 10 000 viti per ettaro. Uno dei criteri più importanti è la disponibilità di acqua e nutrienti. Dove l'acqua è molto scarsa, pochissima pioggia e niente irrigazione, conviene una densità bassa: ogni vite può esplorare un grande volume di suolo senza competere con le vicine.",
   "La densité est le nombre de pieds par hectare, c'est-à-dire par carré de 100 mètres de côté ; un acre vaut environ 0,4 hectare. Elle va de 1 000 à 10 000 pieds par hectare. L'un des critères les plus importants est la disponibilité en eau et en nutriments. Là où l'eau est très rare, très peu de pluie et pas d'irrigation, une faible densité convient : chaque pied explore un grand volume de sol sans concurrence.",
   "Planting density is the number of vines per hectare, a square with 100-metre sides; one acre is about 0.4 hectares. It ranges from 1,000 to 10,000 vines per hectare. A key factor is the availability of water and nutrients. Where water is very limited, very little rain and no irrigation, low density helps: each vine's roots can draw on a large volume of soil without competing with neighbours."),
  v:()=>fSvg(`<rect x="20" y="30" width="120" height="120" fill="#b08a5a"/><rect x="180" y="30" width="120" height="120" fill="#7a8f45"/>`+Array.from({length:9},(_,i)=>`<circle cx="${40+(i%3)*40}" cy="${50+Math.floor(i/3)*40}" r="5" fill="#3f5a23"/>`).join("")+Array.from({length:64},(_,i)=>`<circle cx="${188+(i%8)*14.5}" cy="${38+Math.floor(i/8)*14.5}" r="3.4" fill="#3f5a23"/>`).join("")+fT(80,172,"≈ 1000 / ha",10)+fT(240,172,"≈ 10 000 / ha",10)+fChip(80,190,w3("poca acqua","peu d'eau","little water")))},
 {h:I3("Densità, nutrienti e numero di gemme","Densité, nutriments et nombre de bourgeons","Density, nutrients and bud numbers"),
  c:I3("Con suolo poco fertile ma pioggia sufficiente la vite crescerebbe troppo in foglie: si pianta fitto, così la competizione tra le radici frena la vegetazione. Conta anche il giusto numero di gemme dopo la potatura: con troppe poche ogni gemma ha troppa energia e cresce vigorosa, con troppe la vite non riesce a maturare il raccolto. È la regola in molti vigneti europei. Su suoli molto fertili, comuni nel Nuovo Mondo, la densità alta non basta: si pianta rado, con viti a più cordoni o capi, che danno buona qualità anche con rese alte.",
   "Avec un sol peu fertile mais assez de pluie, la vigne pousserait trop en feuilles : on plante serré, et la concurrence entre racines freine la végétation. Compte aussi le bon nombre de bourgeons après la taille : avec trop peu, chacun a trop d'énergie et pousse vigoureusement ; avec trop, la vigne ne parvient pas à mûrir sa récolte. C'est la règle dans beaucoup de vignobles européens. Sur des sols très fertiles, fréquents dans le Nouveau Monde, la haute densité ne suffit pas : on plante peu dense, avec des vignes à plusieurs cordons ou baguettes, qui donnent une bonne qualité même à fort rendement.",
   "With poor soil but enough rain the vine would grow too much leaf: it is planted at high density so competition between roots restricts growth. The right number of buds after pruning also matters: with too few, each bud has too much energy and grows vigorously; with too many, the vine struggles to ripen its crop. This is common in many European vineyards. On very fertile soils, common in the New World, high density is not enough: vines are planted at low density with multiple cordons or canes, giving good quality even at high yields."),
  v:()=>fSvg(fBox(14,30,140,50,w3("poco fertile + pioggia → densità alta","peu fertile + pluie → densité forte","low fertility + rain → high density"),{fill:"rgba(94,140,49,.45)"})+fBox(166,30,140,50,w3("molto fertile → bassa densità, più cordoni","très fertile → faible densité, plusieurs cordons","very fertile → low density, multiple cordons"),{fill:"rgba(212,162,58,.35)"})+fD(1.6,fTable(null,[[I3("poche gemme","peu de bourgeons","too few buds"),I3("troppo vigore","trop de vigueur","too vigorous")],[I3("troppe gemme","trop de bourgeons","too many buds"),I3("non matura","mûrit mal","struggles to ripen")]],[],{y:100,rh:34,w:280,c1:140})))},
 {h:I3("Due esempi di scelte","Deux exemples de choix","Two worked examples"),
  c:I3("Primo esempio: regione interna, calda e molto soleggiata, con pochissima pioggia e niente irrigazione, ma suolo che trattiene l'acqua. Il problema principale è l'acqua: si pianta a bassa densità; per evitare le scottature si scelgono alberelli o spalliere con cime ricadenti, senza rischio di malattie perché piove poco. Secondo esempio: regione costiera moderata, piovosa tutto l'anno, suolo poco fertile. Si pianta fitto per frenare il vigore e si usa la VSP, che tiene la chioma aperta alla luce e all'aria contro le malattie.",
   "Premier exemple : région intérieure, chaude et très ensoleillée, avec très peu de pluie et sans irrigation, mais un sol qui retient l'eau. Le défi principal est l'eau : on plante à faible densité ; pour éviter l'échaudage on choisit le gobelet ou un palissage à rameaux retombants, sans risque de maladies puisqu'il pleut peu. Second exemple : région côtière modérée, pluvieuse toute l'année, sol peu fertile. On plante dense pour freiner la vigueur et on utilise le VSP, qui garde le feuillage ouvert à la lumière et à l'air contre les maladies.",
   "Example one: an inland region, hot and very sunny, with very little rain and no irrigation, but soil that holds water well. Water is the main challenge: vines are planted at low density; to avoid sunburn they are grown as bush vines or on a trellis with tips flopping over, with little disease risk because it rarely rains. Example two: a moderate coastal region, rainy all year, with low soil fertility. Vines are planted at high density to restrain vigour and trained with VSP, keeping the canopy open to light and air against disease."),
  v:()=>`<svg class="fsvg" viewBox="0 0 320 200" aria-hidden="true">${fDefs}<rect width="160" height="200" fill="#ffd27a"/><rect x="160" width="160" height="200" fill="#a9c3d6"/>${fGround()}${vForm("bush","canopy",50,172)}${vForm("bush","canopy",120,172)}<g transform="translate(160 0) scale(.5 1)">${vForm("cordon","canopy",160,172)}</g>${fChip(80,26,w3("bassa densità · alberelli","faible densité · gobelets","low density · bush vines"))}${fChip(240,26,w3("alta densità · VSP","forte densité · VSP","high density · VSP"))}</svg>`},
 {h:I3("Le rese","Les rendements","Yields"),
  c:I3("La resa è la quantità d'uva prodotta: in tonnellate d'uva o in ettolitri di vino per ettaro. Prevederla serve per rispettare le leggi, come nell'UE, i contratti, o semplicemente per sapere quante vasche servono. Si stima dal numero di gemme lasciate con la potatura, ma gelo, cattiva allegagione e malattie possono ridurla molto. Se è troppo alta si può fare il diradamento dei grappoli poco dopo l'invaiatura: è rischioso, perché se fatto al momento sbagliato la vite compensa ingrossando gli acini rimasti e diluendone i sapori. Il legame tra resa bassa e qualità non è affatto automatico.",
   "Le rendement est la quantité de raisin produite : en tonnes de raisin ou en hectolitres de vin par hectare. Le prévoir sert à respecter la loi, comme dans l'UE, les contrats, ou simplement à savoir combien de cuves il faudra. On l'estime d'après le nombre de bourgeons laissés à la taille, mais le gel, une mauvaise nouaison et les maladies peuvent le réduire fortement. S'il est trop élevé, on peut vendanger en vert peu après la véraison : c'est risqué, car au mauvais moment la vigne compense en grossissant les baies restantes et dilue leurs arômes. Le lien entre faible rendement et qualité n'a rien d'automatique.",
   "Yield is the amount of grapes produced: tonnes of grapes or hectolitres of wine per hectare. Predicting it matters for legal limits, as in the EU, for contracts, or simply to know how much tank space is needed. It is estimated from the number of buds left after pruning, but frost, poor fruit set and disease can cut it sharply. If it looks too high, green harvesting shortly after véraison can reduce it: this is risky, because if done at the wrong time the vine compensates by enlarging the remaining berries and diluting their flavour. The link between low yields and quality is far from automatic."),
  v:()=>fSvg(fGround()+vForm("cordon","canopy",160,172)+[100,160,220].map((x,i)=>`<g>${fBunch(x,116,.8,"#9cc65a")}<animateTransform attributeName="transform" type="translate" from="0 0" to="0 60" dur="1.5s" begin="${1+i*.4}s" fill="freeze"/></g>`).join("")+fChip(160,24,w3("t/ha · hl/ha","t/ha · hl/ha","t/ha · hl/ha"))+fD(1,fChip(250,150,w3("diradamento","vendange en vert","green harvest"),"#5e8c31")),"summer")}
]},
{id:"pests",sec:"v",ch:"vgm",ic:"surv",t:I3("Parassiti, malattie e modi di coltivare","Ravageurs, maladies et modes de culture","Pests, diseases and ways of farming"),s:[
 {h:I3("Fillossera e nematodi","Phylloxéra et nématodes","Phylloxera and nematodes"),
  c:I3("Le viti soffrono molti parassiti e malattie, che riducono la resa o la qualità; danneggiando le foglie limitano anche la fotosintesi. Oltre alla fillossera ci sono i nematodi, vermi microscopici che attaccano le radici, ostacolano l'assorbimento di acqua e nutrienti e possono trasmettere virus. Meglio prevenire: si sanifica il suolo prima del reimpianto e si usano portinnesti resistenti.",
   "Les vignes subissent de nombreux ravageurs et maladies, qui réduisent le rendement ou la qualité ; en abîmant les feuilles, ils limitent aussi la photosynthèse. Outre le phylloxéra, il y a les nématodes, des vers microscopiques qui attaquent les racines, gênent l'absorption d'eau et de nutriments et peuvent transmettre des virus. Mieux vaut prévenir : on assainit le sol avant de replanter et on utilise des porte-greffes résistants.",
   "Vines suffer from many pests and diseases that reduce yield or quality; damaging the leaves also limits photosynthesis. Besides phylloxera there are nematodes, microscopic worms that attack the roots, interfere with water and nutrient uptake and can transmit viruses. Prevention is better than cure: soil is sanitised before replanting and resistant rootstocks are used."),
  v:()=>fSvg(fGround()+`<rect y="174" width="320" height="26" fill="#5a4030"/>`+vForm("headspur","canopy",160,172)+fRoots(160,174)+fWorm(120,188)+fWorm(186,192)+fWorm(150,196)+fChip(240,140,w3("nematodi","nématodes","nematodes"),"#b5334a"),"spring")},
 {h:I3("Uccelli, mammiferi e insetti","Oiseaux, mammifères et insectes","Birds, mammals and insects"),
  c:I3("Uccelli e mammiferi possono mangiare grandi quantità d'uva, e gli acini mezzi mangiati favoriscono le muffe. Contro gli uccelli la soluzione migliore sono spesso le reti; contro conigli, cervi o cinghiali servono recinzioni. Gli insetti mangiano uva e foglie: si combattono con insetticidi o con metodi più rispettosi dell'ambiente come la lotta integrata.",
   "Oiseaux et mammifères peuvent manger de grandes quantités de raisin, et les baies à moitié mangées favorisent les moisissures. Contre les oiseaux, la meilleure solution est souvent le filet ; contre lapins, cerfs ou sangliers il faut des clôtures. Les insectes mangent raisins et feuilles : on les combat avec des insecticides ou par des méthodes plus respectueuses comme la lutte intégrée.",
   "Birds and mammals can eat large quantities of grapes, and half-eaten berries invite fungal disease. Netting is often the best option against birds, while fencing may be needed against rabbits, deer or wild boar. Insects feed on grapes and leaves: they are controlled with insecticides or more environmentally friendly methods such as integrated pest management."),
  v:()=>fSvg(fGround()+fVine("ripe")+fBird(80,50)+fBird(200,40,1.2)+fD(1.5,fNet(56,46,208,126))+fBug(120,90)+fBug(200,96,"#7a9a3a")+`<path d="M0 172H40M0 160H40M0 148H40" stroke="#a5743f" stroke-width="3"/><path d="M8 140V176M30 140V176" stroke="#7a5236" stroke-width="3"/>`,"summer")},
 {h:I3("Peronospora e oidio","Mildiou et oïdium","Downy and powdery mildew"),
  c:I3("Questi funghi amano gli ambienti caldi e umidi e attaccano tutte le parti verdi della vite, foglie e acini. L'uva colpita perde i sapori fruttati e può dare al vino un gusto ammuffito e amaro.",
   "Ces champignons aiment les milieux chauds et humides et attaquent toutes les parties vertes de la vigne, feuilles et baies. Le raisin atteint perd ses arômes fruités et peut donner au vin un goût de moisi et d'amertume.",
   "These fungi thrive in warm, humid conditions and attack all the green parts of the vine, leaves and grapes alike. Affected grapes lose their fruity flavours and can give the wine a mouldy, bitter taint."),
  v:()=>fSvg(fCloud(160,30,1.5,"#b3bac2",10)+`<g transform="translate(90 120)">${fLeaf(0,0,3.4,0,"#5e8c31")}</g><g transform="translate(230 120)">${fLeaf(0,0,3.4,0,"#5e8c31")}</g>`+fD(1,[[78,92],[96,100],[88,76]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="6" fill="#e3d870" opacity=".85"/>`).join("")+fChip(90,170,w3("peronospora","mildiou","downy mildew")))+fD(1.8,[[218,90],[236,98],[226,78],[244,82]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="7" fill="#fff" opacity=".85"/>`).join("")+fChip(230,170,w3("oidio","oïdium","powdery mildew"))),"spring")},
 {h:I3("Muffa grigia","Pourriture grise","Grey rot"),
  c:I3("È causata dal fungo Botrytis cinerea, che ama l'umidità e attacca soprattutto gli acini: altera i sapori e nelle uve nere fa perdere colore. In condizioni particolari, e su certe uve bianche, la stessa infezione diventa positiva: è la muffa nobile, che dà alcuni dei migliori vini dolci del mondo.",
   "Elle est causée par le champignon Botrytis cinerea, qui aime l'humidité et attaque surtout les baies : il altère les arômes et fait perdre de la couleur aux raisins noirs. Dans des conditions particulières, et sur certains raisins blancs, la même infection devient bénéfique : c'est la pourriture noble, qui donne certains des meilleurs vins liquoreux du monde.",
   "It is caused by the fungus Botrytis cinerea, which thrives in damp conditions and mainly attacks the grapes: it taints flavours and causes colour loss in black grapes. Under specific conditions, and on certain white grapes, the same infection becomes beneficial: noble rot, which produces some of the world's finest sweet wines."),
  v:()=>fSvg(fCloud(160,30,1.8,"#9aa3ab",10)+`<g transform="translate(110 70)">${fBunch(0,0,3,"#5a1f4a")}</g>`+fD(1,`<g transform="translate(110 70)">${[0,1,2,3,4,5,6,7,8].map(k=>`<circle cx="${((k*7)%5-2)*7}" cy="${20+Math.floor(k/3)*12}" r="6" fill="#a7adb3" opacity=".9"/>`).join("")}</g>`)+`<g transform="translate(240 70)">${fBunch(0,0,3,"#d8c45a")}</g>`+fD(2,fChip(110,180,w3("muffa grigia","pourriture grise","grey rot"),"#5c646b")+fChip(240,180,w3("muffa nobile","pourriture noble","noble rot"),"#d4a23a","#2a1b20")),"autumn")},
 {h:I3("Trattamenti e gestione della chioma","Traitements et gestion du feuillage","Sprays and canopy management"),
  c:I3("Le malattie fungine si combattono con i fungicidi: tradizionalmente lo zolfo contro l'oidio e la poltiglia bordolese, a base di rame, contro la peronospora; oggi esistono molti nuovi prodotti. Si spruzza di solito con il trattore, e nei climi marittimi piovosi servono più trattamenti. Tutti i trattamenti devono finire per tempo prima della vendemmia, per non lasciare residui nel vino. Una chioma aperta, ben ventilata e asciutta riduce il rischio di malattie e il numero di trattamenti, che raggiungono meglio tutte le parti della pianta.",
   "Les maladies fongiques se combattent avec des fongicides : traditionnellement le soufre contre l'oïdium et la bouillie bordelaise, à base de cuivre, contre le mildiou ; il existe aujourd'hui de nombreux nouveaux produits. On pulvérise en général au tracteur, et en climat maritime pluvieux il faut plus de traitements. Ils doivent s'arrêter assez tôt avant les vendanges pour ne laisser aucun résidu dans le vin. Un feuillage ouvert, bien ventilé et sec réduit le risque de maladies et le nombre de traitements, qui atteignent mieux toutes les parties de la plante.",
   "Fungal diseases are controlled with fungicides: traditionally sulfur against powdery mildew and Bordeaux mixture, a copper-based spray, against downy mildew; many newer chemicals now exist. Spraying is usually done by tractor, and maritime climates with growing-season rain need more applications. All spraying must stop well before harvest so no residues remain in the wine. An open, airy, dry canopy reduces disease risk and the number of sprays, which also reach every part of the vine more easily."),
  v:()=>fSvg(fGround()+vForm("cordon","canopy",130,172)+`<g><animateTransform attributeName="transform" type="translate" values="40 0;-10 0;40 0" dur="6s" repeatCount="indefinite"/>${fTractor(270,172,1)}</g>`+fChip(70,24,w3("zolfo → oidio","soufre → oïdium","sulfur → powdery"))+fChip(230,24,w3("rame → peronospora","cuivre → mildiou","copper → downy")),"spring")},
 {h:I3("Virus e malattie batteriche","Virus et maladies bactériennes","Viruses and bacterial diseases"),
  c:I3("Molti virus possono infettare la vite: di solito non la uccidono ma ne riducono molto resa e qualità. Sono contagiosi e persistenti e si diffondono con le talee o i nematodi; non esistono cure, e l'unico rimedio è estirpare le viti e sanificare il terreno. Anche molti batteri attaccano la vite, alcuni fino a ucciderla; sono diffusi da piccoli insetti, le cicaline. Si prevengono con quarantene severe e interrompendo il ciclo degli insetti; anche qui, una volta infette, le viti vanno estirpate.",
   "De nombreux virus peuvent infecter la vigne : en général ils ne la tuent pas mais réduisent fortement rendement et qualité. Contagieux et persistants, ils se transmettent par les boutures ou les nématodes ; il n'existe aucun traitement, et le seul remède est d'arracher les vignes et d'assainir le sol. De nombreuses bactéries attaquent aussi la vigne, certaines jusqu'à la tuer ; elles sont propagées par de petits insectes, les cicadelles. On les prévient par une quarantaine stricte et en interrompant le cycle des insectes ; là aussi, une fois infectées, les vignes doivent être arrachées.",
   "Many viruses can infect vines: most do not kill the vine but sharply reduce yield and quality. They are contagious and persistent, spread by cuttings or nematodes; there is no cure, and the only remedy is to dig up the vines and sanitise the land. Many bacteria also infect vines, some fatally; they are spread by small insects called sharpshooters. Prevention relies on strict quarantine and breaking the insects' life cycle; again, once infected, vines must be removed."),
  v:()=>fSvg(fGround()+`<g transform="translate(-60 0)">${vForm("headspur","canopy",160,172)}</g>`+`<g transform="translate(70 0)">${vForm("headspur","bare",160,172)}</g>`+fBug(260,120,"#86b85a")+fBug(240,100,"#86b85a")+fD(1.6,`<path d="M210 70l40 40M250 70l-40 40" stroke="#b5334a" stroke-width="5"/>`)+fChip(230,30,w3("nessuna cura: estirpare","aucun remède : arracher","no cure: dig up")),"summer")},
 {h:I3("Agricoltura sostenibile","Agriculture durable","Sustainable agriculture"),
  c:I3("Nella seconda metà del Novecento l'uso di prodotti chimici e concimi è cresciuto molto, con danni ambientali che preoccupano viticoltori, consumatori e legislatori. Nell'agricoltura sostenibile i prodotti chimici non sono vietati ma limitati: conoscendo il ciclo dei parassiti e seguendo le previsioni meteo, si interviene solo quando serve, con meno trattamenti. La lotta integrata favorisce i predatori naturali dei parassiti: per questo è essenziale la biodiversità, con altre piante tra i filari che poi, falciate e interrate, nutrono il suolo.",
   "Dans la seconde moitié du XXe siècle, l'usage de produits chimiques et d'engrais a fortement augmenté, avec des dégâts environnementaux qui inquiètent vignerons, consommateurs et législateurs. En agriculture durable, les produits chimiques ne sont pas interdits mais limités : en connaissant le cycle des ravageurs et en suivant la météo, on intervient seulement quand il faut, avec moins de traitements. La lutte intégrée favorise les prédateurs naturels des ravageurs : la biodiversité est donc essentielle, avec d'autres plantes entre les rangs qui, fauchées et enfouies, nourrissent le sol.",
   "In the second half of the twentieth century the use of man-made chemicals and fertilisers rose sharply, and the environmental damage worries growers, consumers and legislators. In sustainable agriculture chemicals are not banned but restricted: by understanding pest life cycles and following weather forecasts, growers spray only when needed, so fewer applications are required. Integrated pest management encourages pests' natural predators: biodiversity is therefore essential, with other plants between the rows that, when mowed and ploughed in, also feed the soil."),
  v:()=>fSvg(fGround("#6f8f3a")+fVine("set")+Array.from({length:14},(_,i)=>`<g transform="translate(${14+i*22} 178)"><circle r="3" fill="${["#f3e1a0","#e8a0c0","#fff"][i%3]}"/></g>`).join("")+fBug(110,80,"#c0392b")+fBug(210,96,"#c0392b")+fChip(160,24,w3("lotta integrata · biodiversità","lutte intégrée · biodiversité","IPM · biodiversity"),"#5e8c31"),"spring")},
 {h:I3("Agricoltura biologica","Agriculture biologique","Organic agriculture"),
  c:I3("Riprende molti principi di quella sostenibile, ma ammette solo pochi trattamenti tradizionali e in quantità ridotte. Per scriverlo in etichetta serve la certificazione di un ente, e ogni ente ha regole leggermente diverse. Ovunque è richiesto un periodo di conversione, lavorando già con metodo biologico, prima di ottenere la certificazione.",
   "Elle reprend beaucoup de principes de l'agriculture durable, mais n'autorise que peu de traitements traditionnels, en petites quantités. Pour l'indiquer sur l'étiquette il faut la certification d'un organisme, et chacun a des règles un peu différentes. Partout, une période de conversion en travaillant déjà en bio est exigée avant la certification.",
   "It shares many ideas with sustainable agriculture, but allows only a very limited number of traditional treatments, in small quantities. To state it on the label, certification from an approved body is needed, and each body's standards differ slightly. Everywhere, the vineyard must go through a conversion period farmed to organic standards before it can be certified."),
  v:()=>fSvg(fGround("#6f8f3a")+fVine("set")+`<g transform="translate(250 60)"><circle r="26" fill="#5e8c31"/><path d="M-10 4q10 -24 20 -4q-10 14 -20 4z" fill="#d4ecb0"/></g>`+fD(1.4,fClock(60,60,w3("conversione","conversion","conversion"))),"spring")},
 {h:I3("Agricoltura biodinamica","Agriculture biodynamique","Biodynamic agriculture"),
  c:I3("Si basa sul lavoro di Rudolf Steiner e Maria Thun: adotta le pratiche biologiche ma aggiunge filosofia e cosmologia. Il suolo è visto come parte di un sistema che collega Terra, aria e pianeti, e i lavori seguono i cicli della luna, dei pianeti e delle stelle. Si usano rimedi omeopatici, i «preparati», per nutrire il suolo e contrastare malattie e parassiti. Esistono enti di certificazione anche per la biodinamica.",
   "Elle repose sur les travaux de Rudolf Steiner et Maria Thun : elle adopte les pratiques biologiques mais y ajoute philosophie et cosmologie. Le sol est vu comme partie d'un système reliant la Terre, l'air et les planètes, et les travaux suivent les cycles de la lune, des planètes et des étoiles. On utilise des remèdes homéopathiques, les « préparations », pour nourrir le sol et lutter contre maladies et ravageurs. Il existe aussi des organismes de certification en biodynamie.",
   "It is based on the work of Rudolf Steiner and Maria Thun: it adopts organic practices but adds philosophy and cosmology. The soil is seen as part of a system linking the Earth, the air and the planets, and vineyard work follows the cycles of the moon, planets and stars. Homeopathic remedies called 'preparations' are used to fertilise the soil and fight disease and pests. Biodynamic certification bodies also exist."),
  v:()=>fSvg(fMoon(70,40)+fGround("#3b3a4a")+fVine("bud")+`<g transform="translate(250 60)"><circle r="10" fill="#f3cd8a"/><ellipse rx="22" ry="6" fill="none" stroke="#f3cd8a"/></g>`+fChip(160,190,"Steiner · Thun"),"night")}
]},
{id:"harvest",sec:"v",ch:"vgm",ic:"order",t:I3("La vendemmia","Les vendanges","Harvest"),s:[
 {h:I3("Quando vendemmiare","Quand vendanger","When to pick"),
  c:I3("Dall'invaiatura l'uva matura: lo zucchero sale, l'acidità scende, si sviluppano gli aromi tipici e i tannini delle bucce diventano meno amari e astringenti. Misurare lo zucchero è il modo più comune per seguire la maturazione. Non esiste una regola fissa: l'equilibrio ideale tra zucchero, acidità, aromi e tannini dipende dalla varietà, dal clima e soprattutto dallo stile e dalla qualità del vino che si vuole fare.",
   "Dès la véraison le raisin mûrit : le sucre monte, l'acidité baisse, les arômes typiques se développent et les tanins des peaux deviennent moins amers et astringents. Mesurer le sucre est la façon la plus courante de suivre la maturation. Il n'existe pas de règle fixe : l'équilibre idéal entre sucre, acidité, arômes et tanins dépend du cépage, du climat et surtout du style et de la qualité du vin recherché.",
   "From véraison the grapes ripen: sugar rises, acidity falls, signature flavours develop and the skin tannins become less bitter and astringent. Monitoring sugar is the most common way to track ripening. There is no hard and fast rule: the ideal balance of sugar, acid, flavour and tannin depends on the variety, the climate and above all the style and quality of wine being made."),
  v:()=>fSvg(fGround()+fVine("ripe")+`<g transform="translate(250 70)"><rect x="-20" y="-30" width="40" height="60" rx="6" fill="#2a1b20" stroke="#d4a23a"/><path d="M-12 -18h24M-12 -6h24" stroke="#d4a23a"/>${fT(0,18,"°Brix",9,"#f3cd8a")}</g>`+fChip(110,24,w3("zucchero · acidità · aromi · tannini","sucre · acidité · arômes · tanins","sugar · acid · flavour · tannin")),"autumn")},
 {h:I3("Il meteo e la cantina","La météo et le chai","Weather and winery logistics"),
  c:I3("Idealmente si raccoglie quando l'uva ha esattamente le qualità volute. A volte però il cattivo tempo costringe ad anticipare per salvare il raccolto: la grandine può distruggere l'uva e la pioggia può gonfiarla e diluirne il succo. Bisogna anche coordinare gli arrivi in cantina, perché non venga sommersa da più uva di quanta possa lavorarne.",
   "Idéalement on récolte quand le raisin a exactement les qualités voulues. Mais parfois le mauvais temps oblige à avancer la date pour sauver la récolte : la grêle peut détruire le raisin et la pluie le faire gonfler et diluer le jus. Il faut aussi coordonner les arrivées au chai, pour qu'il ne soit pas submergé par plus de raisin qu'il ne peut en traiter.",
   "Ideally harvest begins when the grapes have exactly the qualities needed. Sometimes, though, bad weather forces an earlier pick to save the crop: hail can destroy grapes and rain can swell them and dilute the juice. Deliveries to the winery must also be coordinated so it is not overwhelmed with more fruit than it can process."),
  v:()=>fSvg(fCloud(80,34,1.8,"#5b6270",10)+fGround()+fVine("ripe",-60)+`<g transform="translate(260 120)"><rect x="-40" y="-40" width="80" height="60" fill="#8a5a33"/><path d="M-46 -40L0 -70L46 -40Z" fill="#6b4426"/><rect x="-12" y="-6" width="24" height="26" fill="#2a1b20"/></g>`+[0,1,2].map(i=>`<g>${fCrate(150,170)}<animateTransform attributeName="transform" type="translate" from="${-20+i*0} 0" to="70 0" dur="3s" begin="${i}s" repeatCount="indefinite"/></g>`).join(""),"autumn")},
 {h:I3("La vendemmia a macchina","La vendange mécanique","Machine harvesting"),
  c:I3("La vendemmiatrice scavalca il filare e scuote i tronchi: gli acini maturi cadono e vengono raccolti, mentre i raspi restano sulla pianta. Non è selettiva: raccoglie anche acini malati, acerbi o danneggiati, e fa cadere pezzi di foglie, insetti e altro materiale, il MOG, cioè «materia diversa dall'uva». Questi elementi si possono togliere con la cernita in cantina, ma nelle grandi produzioni non sempre è possibile.",
   "La machine à vendanger enjambe le rang et secoue les troncs : les baies mûres tombent et sont récupérées, tandis que les rafles restent sur le pied. Elle n'est pas sélective : elle récolte aussi des baies malades, pas mûres ou abîmées, et fait tomber morceaux de feuilles, insectes et autres débris, le MOG, « matières autres que le raisin ». On peut les éliminer au tri en cave, mais dans les grosses productions ce n'est pas toujours possible.",
   "The harvester straddles the row and shakes the vine trunks: ripe berries fall off and are collected, leaving the stalks behind. It is not selective: it also collects unhealthy, unripe and damaged grapes and shakes off bits of leaf, insects and other contaminants, called MOG, 'matter other than grapes'. These can be removed by sorting at the winery, but at large scale this is not always possible."),
  v:()=>fSvg(fGround()+`<g><animateTransform attributeName="transform" type="translate" values="-60 0;60 0;-60 0" dur="8s" repeatCount="indefinite"/>${fHarvester(160,170)}</g>`+fVine("ripe",-130)+fChip(60,26,"MOG","#b5334a"),"autumn")},
 {h:I3("Pro e contro della macchina","Atouts et limites de la machine","Machine pros and cons"),
  c:I3("Il grande vantaggio è la velocità: decisiva se il maltempo minaccia o con varietà come il Sauvignon Blanc, che diventano troppo mature in fretta. Le macchine lavorano anche di notte, portando in cantina uva fresca: si risparmia energia per raffreddarla e si rallenta l'ossidazione. Però funzionano solo su terreni piani o in leggera pendenza, con varietà che si staccano facilmente, e non servono per gli stili che richiedono grappoli interi, come Beaujolais o Champagne.",
   "Le grand avantage est la vitesse : décisive si le mauvais temps menace ou avec des cépages comme le Sauvignon Blanc, qui deviennent vite trop mûrs. Les machines travaillent aussi la nuit, apportant au chai un raisin frais : on économise l'énergie pour le refroidir et on ralentit l'oxydation. Mais elles ne fonctionnent que sur terrain plat ou en pente douce, avec des cépages qui se détachent facilement, et ne conviennent pas aux styles qui exigent des grappes entières, comme le Beaujolais ou la Champagne.",
   "The big advantage is speed: vital when bad weather threatens or with varieties such as Sauvignon Blanc that become over-ripe quickly. Machines can also work at night, bringing cool grapes to the winery: this saves the energy needed to chill them and slows oxidation. But they only work on flat or gently sloping land, with varieties whose berries come away easily, and cannot be used for styles needing whole bunches, such as Beaujolais or Champagne."),
  v:()=>fSvg(fMoon(280,30)+fGround("#3b3a4a")+`<g><animateTransform attributeName="transform" type="translate" values="-60 0;60 0;-60 0" dur="8s" repeatCount="indefinite"/>${fHarvester(160,170)}</g>`+fChip(70,26,w3("di notte, uva fresca","de nuit, raisin frais","at night, cool fruit"))+fD(1.5,fChip(240,60,w3("no grappoli interi","pas de grappes entières","no whole bunches"),"#b5334a")),"night")},
 {h:I3("La vendemmia a mano","La vendange manuelle","Hand harvesting"),
  c:I3("I vendemmiatori tagliano i grappoli uno per uno con le forbici. È più lenta e richiede molta manodopera, quindi può costare di più. Però permette di scegliere già in vigna, lasciando sulla pianta l'uva marcia o acerba. Per l'uva con muffa nobile è indispensabile, perché la muffa si sviluppa in modo diverso da grappolo a grappolo e persino all'interno dello stesso grappolo.",
   "Les vendangeurs coupent les grappes une à une au sécateur. C'est plus lent et demande beaucoup de main-d'œuvre, donc peut coûter plus cher. Mais cela permet de trier dès la vigne, en laissant sur le pied le raisin pourri ou pas mûr. Pour le raisin botrytisé c'est indispensable, car la pourriture noble se développe différemment d'une grappe à l'autre, et même au sein d'une même grappe.",
   "Pickers cut off individual bunches with secateurs. It is slower and labour-intensive, so it can cost more. But it allows selection in the vineyard, leaving rotten or unripe grapes on the vine. For grapes with noble rot it is essential, because the rot develops differently from bunch to bunch and even within a single bunch."),
  v:()=>fSvg(fGround()+fVine("ripe")+fMan(60,172,1.1,"#8c1d40")+fMan(270,172,1.1,"#1f6f6b","carry")+fCrate(110,174)+`<g>${fBunch(100,120,1,"#6b2d5c")}<animateTransform attributeName="transform" type="translate" values="0 0;8 46;8 46" dur="2s" repeatCount="indefinite"/></g>`,"autumn")},
 {h:I3("Grappoli interi e pendii ripidi","Grappes entières et pentes raides","Whole bunches and steep slopes"),
  c:I3("A mano l'uva si rovina meno, soprattutto se trasportata in cassette basse e impilabili. I raspi restano attaccati: si ottengono grappoli interi e intatti, che danno un succo pulito e puro nella pressatura dei bianchi e sono indispensabili per la fermentazione a grappolo intero dei rossi. Sui pendii ripidi, come nel Douro, nella Mosella e nel Rodano settentrionale, la vendemmia a mano è spesso l'unica possibile.",
   "À la main le raisin s'abîme moins, surtout s'il est transporté dans des caissettes basses et empilables. Les rafles restent attachées : on obtient des grappes entières et intactes, qui donnent un jus net et pur au pressurage des blancs et sont indispensables à la fermentation en grappes entières des rouges. Sur les pentes raides, comme dans le Douro, la Moselle et le Rhône septentrional, la vendange manuelle est souvent la seule possible.",
   "Hand-picked grapes suffer less damage, especially if carried in shallow, stackable trays. Stems are retained: the result is whole, intact bunches that give clean, pure juice when pressed for white wine and are essential for whole-bunch fermentation of reds. On steep slopes, such as in the Douro, the Mosel and the Northern Rhône, hand picking is often the only option."),
  v:()=>fSvg(`<path d="M0 200L0 160L320 30V200Z" fill="#7a6a4a"/>`+fRows(20,190,300,50,10)+fMan(120,140,.9,"#8c1d40","carry")+fMan(220,100,.9,"#1f6f6b","carry")+`<g transform="translate(60 180)">${[0,1,2].map(i=>`<rect x="-20" y="${-i*9}" width="40" height="8" rx="2" fill="#a5743f" stroke="#7a5236"/>`).join("")}</g>`+fChip(220,180,"Douro · Mosel · Côte-Rôtie"),"autumn")}
]}
);
